fun isLambda decls b =>
  have xs := Array.map Lean.LocalDecl.toExpr decls;
  have b := b.abstract xs;
  decls.size.foldRev
    (fun i x b =>
      have decl := decls[i];
      match decl with
      | Lean.LocalDecl.cdecl index fvarId n ty bi kind =>
        have ty := ty.abstractRange i xs;
        if isLambda = true then Lean.mkLambda n bi ty b else Lean.mkForall n bi ty b
      | Lean.LocalDecl.ldecl index fvarId n ty val nondep kind =>
        if b.hasLooseBVar 0 = true then
          have ty := ty.abstractRange i xs;
          have val := val.abstractRange i xs;
          Lean.mkLet n ty val b nondep
        else b.lowerLooseBVars 1 1)
    b

